);

  wire       _ram_len_ext_R0_en = 1'h1;
  wire       _ram_id_ext_R0_en = 1'h1;
  reg  [2:0] enq_ptr_value;
  reg  [2:0] deq_ptr_value;
  reg        maybe_full;
  wire       ptr_match = enq_ptr_value == deq_ptr_value;
  wire       empty = ptr_match & ~maybe_full;
  wire       full = ptr_match & maybe_full;
  wire       do_enq = ~full & io_enq_valid;
  wire       do_deq = io_deq_ready & ~empty;
  always @(posedge clock) begin
    if (reset) begin
      enq_ptr_value <= 3'h0;
      deq_ptr_value <= 3'h0;
      maybe_full <= 1'h0;
    end
    else begin
      if (do_enq)
        enq_ptr_value <= enq_ptr_value + 3'h1;
      if (do_deq)
        deq_ptr_value <= deq_ptr_value + 3'h1;
      if (~(do_enq == do_deq))
        maybe_full <= do_enq;
    end
  end // always @(posedge)
  ram_id_8x4 ram_id_ext (
    .R0_addr (deq_ptr_value),
    .R0_en   (_ram_id_ext_R0_en),
    .R0_clk  (clock),
    .R0_data (io_deq_bits_id),
    .W0_addr (enq_ptr_value),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data (io_enq_bits_id)
  );
  ram_len_8x8 ram_len_ext (
    .R0_addr (deq_ptr_value),
    .R0_en   (_ram_len_ext_R0_en),
    .R0_clk  (clock),
    .R0_data (io_deq_bits_len),
    .W0_addr (enq_ptr_value),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data (io_enq_bits_len)
  );
  assign io_enq_ready = ~full;
  assign io_deq_valid = ~empty;
endmodule

module DDR3Bridge(
  input          clock,
                 reset,
                 io_ddr_clk,
                 io_ddr_rstn,
  input  [3:0]   io_axi_ar_arid,
  input  [31:0]  io_axi_ar_araddr,
  input  [7:0]   io_axi_ar_arlen,
  input  [2:0]   io_axi_ar_arsize,
  input  [1:0]   io_axi_ar_arburst,
  input  [2:0]   io_axi_ar_arlock,
  input  [3:0]   io_axi_ar_arcache,
  input  [2:0]   io_axi_ar_arprot,
  input          io_axi_ar_arvalid,
  output         io_axi_ar_arready,
  output [3:0]   io_axi_r_rid,
  output [63:0]  io_axi_r_rdata,
  output [1:0]   io_axi_r_rresp,
  output         io_axi_r_rlast,
                 io_axi_r_rvalid,
  input          io_axi_r_rready,
  input  [3:0]   io_axi_aw_awid,
  input  [31:0]  io_axi_aw_awaddr,
  input  [7:0]   io_axi_aw_awlen,
  input  [2:0]   io_axi_aw_awsize,
  input  [1:0]   io_axi_aw_awburst,
                 io_axi_aw_awlock,
  input  [3:0]   io_axi_aw_awcache,
  input  [2:0]   io_axi_aw_awprot,
  input          io_axi_aw_awvalid,
  output         io_axi_aw_awready,
  input  [3:0]   io_axi_w_wid,
  input  [63:0]  io_axi_w_wdata,
  input  [7:0]   io_axi_w_wstrb,
  input          io_axi_w_wlast,
                 io_axi_w_wvalid,
  output         io_axi_w_wready,
  output [3:0]   io_axi_b_bid,
  output [1:0]   io_axi_b_bresp,
  output         io_axi_b_bvalid,
  input          io_axi_b_bready,
  output [27:0]  io_ddrAwAddr,
  output [3:0]   io_ddrAwLen,
  output         io_ddrAwValid,
  input          io_ddrAwReady,
  output [255:0] io_ddrWData,
  output [31:0]  io_ddrWStrb,
  input          io_ddrWReady,
  output [27:0]  io_ddrArAddr,
  output [3:0]   io_ddrArLen,
  output         io_ddrArValid,
  input          io_ddrArReady,
  input  [255:0] io_ddrRData,
  input          io_ddrRValid,
                 io_ddrRLast,
  output [2:0]   io_dbgOutW,
                 io_dbgOutR,
                 io_dbgMaxOutW,
                 io_dbgMaxOutR
);

  wire         _rdQ_io_deq_ready;
  wire         _rdQ_io_enq_ready;
  wire         _rdQ_io_deq_valid;
  wire [7:0]   _rdQ_io_deq_bits_len;
  wire [27:0]  _awQ_io_enq_bits_addr;
  wire         _awQ_io_enq_ready;
  wire         _awQ_io_deq_valid;
  wire [27:0]  _awQ_io_deq_bits_addr;
  wire [7:0]   _awQ_io_deq_bits_len;
  wire [3:0]   _awQ_io_deq_bits_id;
  wire         _doneCdc_io_enq_valid;
  wire         _doneCdc_io_dRstn;
  wire         _doneCdc_io_deq_valid;
  wire         _rCdc_io_dRstn;
  wire         _rCdc_io_deq_ready;
  wire         _rCdc_io_enq_ready;
  wire [2:0]   _rCdc_io_sOcc;
  wire         _rCdc_io_deq_valid;
  wire [255:0] _rCdc_io_deq_bits;
  wire         _arCdc_io_sRstn;
  wire         _arCdc_io_deq_ready;
  wire         _arCdc_io_enq_ready;
  wire         _arCdc_io_deq_valid;
  wire         _wCdc_io_sRstn;
  wire [255:0] _wCdc_io_enq_bits_data;
  wire [31:0]  _wCdc_io_enq_bits_strb;
  wire         _wCdc_io_enq_ready;
  wire         _wCdc_io_deq_valid;
  wire [3:0]   _wCdc_io_deq_bits_id;
  wire         _wCdc_io_deq_bits_last;
  wire         _awCdc_io_sRstn;
  wire         _awCdc_io_deq_ready;
  wire         _awCdc_io_enq_ready;
  wire         _awCdc_io_deq_valid;
  reg  [2:0]   outW;
  reg  [2:0]   maxOutW;
  wire         _awQ_io_enq_valid_T_1 = io_axi_aw_awvalid & ~(outW[2]);
  reg          wqValid;
  reg  [3:0]   wqId;
  reg  [27:0]  wqAddr;
  reg  [8:0]   wqLeft;
  reg  [6:0]   wqGrpLeft;
  reg  [2:0]   wrFill;
  reg  [63:0]  wrBuf_0;
  reg  [63:0]  wrBuf_1;
  reg  [63:0]  wrBuf_2;
  reg  [63:0]  wrBuf_3;
  reg  [7:0]   wrStrb_0;
  reg  [7:0]   wrStrb_1;
  reg  [7:0]   wrStrb_2;
  reg  [7:0]   wrStrb_3;
  reg          wrAgg;
  wire         wLoad = ~wqValid & _awQ_io_deq_valid;
  wire         io_axi_w_wready_0 = wqValid & wrAgg;
  wire         wBeatOut_last = wqGrpLeft == 7'h1;
  wire         wPushOk = wqValid & ~wrAgg & _awCdc_io_enq_ready & _wCdc_io_enq_ready;
  reg  [2:0]   outR;
  reg  [2:0]   maxOutR;
  reg          arSplit;
  reg  [27:0]  arAddr;
  reg  [6:0]   arGrpLeft;
  wire         arReady = ~arSplit & _rdQ_io_enq_ready & ~(outR[2]);
  wire         _rdQ_io_enq_valid_T = arReady & io_axi_ar_arvalid;
  reg  [1:0]   rdOffset;
  reg  [7:0]   rdBeatCnt;
  reg  [255:0] rdBuf;
  wire         rdNew = rdOffset == 2'h0;
  wire         io_axi_r_rvalid_0 = _rdQ_io_deq_valid & ((|rdOffset) | _rCdc_io_deq_valid);
  wire         io_axi_r_rlast_0 = rdBeatCnt == _rdQ_io_deq_bits_len;
  wire [255:0] _io_axi_r_rdata_T = rdNew ? _rCdc_io_deq_bits : rdBuf;
  wire [255:0] _io_axi_r_rdata_T_2 = _io_axi_r_rdata_T >> {248'h0, rdOffset, 6'h0};
  wire         _rCdc_io_deq_ready_T = rdNew & io_axi_r_rvalid_0;
  wire         rFire = io_axi_r_rvalid_0 & io_axi_r_rready;
  reg  [3:0]   ipWrPend;
  wire         wTake = io_ddrWReady & _wCdc_io_deq_valid & (|ipWrPend);
  reg  [3:0]   inflightR;
  wire         arGo = _arCdc_io_deq_valid & inflightR < {1'h0, 3'h4 - _rCdc_io_sOcc};
  wire         _GEN = io_axi_w_wready_0 & io_axi_w_wvalid;
  wire         _GEN_0 = _GEN & wrFill[1:0] == 2'h0;
  wire         _GEN_1 = _GEN & wrFill[1:0] == 2'h1;
  wire         _GEN_2 = _GEN & wrFill[1:0] == 2'h2;
  wire         _GEN_3 = _GEN & (&(wrFill[1:0]));
  wire         _GEN_4 = _rdQ_io_enq_ready & _rdQ_io_enq_valid_T;
  wire         _GEN_5 = arSplit & _arCdc_io_enq_ready;
  wire         _GEN_6 = arGrpLeft == 7'h1;
  always @(posedge clock) begin
    if (reset) begin
      outW <= 3'h0;
      maxOutW <= 3'h0;
      wqValid <= 1'h0;
      wrAgg <= 1'h1;
      outR <= 3'h0;
      maxOutR <= 3'h0;
      arSplit <= 1'h0;
      rdOffset <= 2'h0;
      rdBeatCnt <= 8'h0;
    end
    else begin
      outW <=
        outW + {2'h0, _awQ_io_enq_ready & _awQ_io_enq_valid_T_1}
        - {2'h0, _doneCdc_io_deq_valid & io_axi_b_bready};
      if (outW > maxOutW)
        maxOutW <= outW;
      wqValid <= ~(wPushOk & wBeatOut_last) & (wLoad | wqValid);
      wrAgg <= wPushOk | ~(_GEN & (wrFill == 3'h3 | wqLeft == 9'h1)) & (wLoad | wrAgg);
      outR <=
        outR + {2'h0, io_axi_ar_arvalid & arReady} - {2'h0, rFire & io_axi_r_rlast_0};
      if (outR > maxOutR)
        maxOutR <= outR;
      arSplit <= ~(_GEN_5 & _GEN_6) & (_GEN_4 | arSplit);
      if (rFire) begin
        if (io_axi_r_rlast_0 | (&rdOffset))
          rdOffset <= 2'h0;
        else
          rdOffset <= rdOffset + 2'h1;
        if (io_axi_r_rlast_0)
          rdBeatCnt <= 8'h0;
        else
          rdBeatCnt <= rdBeatCnt + 8'h1;
      end
    end
    if (wLoad)
      wqId <= _awQ_io_deq_bits_id;
    if (wPushOk) begin
      if (wBeatOut_last)
        wqAddr <= 28'h0;
      else
        wqAddr <= wqAddr + 28'h8;
      wrFill <= 3'h0;
      wrStrb_0 <= 8'h0;
      wrStrb_1 <= 8'h0;
      wrStrb_2 <= 8'h0;
      wrStrb_3 <= 8'h0;
    end
    else begin
      if (wLoad)
        wqAddr <= _awQ_io_deq_bits_addr;
      if (_GEN)
        wrFill <= wrFill + 3'h1;
      else if (wLoad)
        wrFill <= 3'h0;
      if (_GEN_0)
        wrStrb_0 <= io_axi_w_wstrb;
      else if (wLoad)
        wrStrb_0 <= 8'h0;
      if (_GEN_1)
        wrStrb_1 <= io_axi_w_wstrb;
      else if (wLoad)
        wrStrb_1 <= 8'h0;
      if (_GEN_2)
        wrStrb_2 <= io_axi_w_wstrb;
      else if (wLoad)
        wrStrb_2 <= 8'h0;
      if (_GEN_3)
        wrStrb_3 <= io_axi_w_wstrb;
      else if (wLoad)
        wrStrb_3 <= 8'h0;
    end
    if (_GEN)
      wqLeft <= wqLeft - 9'h1;
    else if (wLoad)
      wqLeft <= {1'h0, _awQ_io_deq_bits_len + 8'h1};
    if (~wPushOk | wBeatOut_last) begin
      if (wLoad)
        wqGrpLeft <= {1'h0, _awQ_io_deq_bits_len[7:2] + 6'h1};
    end
    else
      wqGrpLeft <= wqGrpLeft - 7'h1;
    if (_GEN_0)
      wrBuf_0 <= io_axi_w_wdata;
    if (_GEN_1)
      wrBuf_1 <= io_axi_w_wdata;
    if (_GEN_2)
      wrBuf_2 <= io_axi_w_wdata;
    if (_GEN_3)
      wrBuf_3 <= io_axi_w_wdata;
    if (~_GEN_5 | _GEN_6) begin
      if (_GEN_4) begin
        arAddr <= io_axi_ar_araddr[29:2];
        arGrpLeft <= {1'h0, io_axi_ar_arlen[7:2] + 6'h1};
      end
    end
    else begin
      arAddr <= arAddr + 28'h8;
      arGrpLeft <= arGrpLeft - 7'h1;
    end
    if (_rCdc_io_deq_ready_T & io_axi_r_rready)
      rdBuf <= _rCdc_io_deq_bits;
  end // always @(posedge)
  always @(posedge io_ddr_clk) begin
    if (~io_ddr_rstn) begin
      ipWrPend <= 4'h0;
      inflightR <= 4'h0;
    end
    else begin
      ipWrPend <= ipWrPend + {3'h0, _awCdc_io_deq_valid & io_ddrAwReady} - {3'h0, wTake};
      inflightR <=
        inflightR + {3'h0, arGo & io_ddrArReady}
        - {3'h0, io_ddrRValid & _rCdc_io_enq_ready};
    end
  end // always @(posedge)
  assign _awCdc_io_sRstn = ~reset;
  assign _awCdc_io_deq_ready = _awCdc_io_deq_valid & io_ddrAwReady;
  CdcFifo awCdc (
    .io_sClk          (clock),
    .io_sRstn         (_awCdc_io_sRstn),
    .io_enq_ready     (_awCdc_io_enq_ready),
    .io_enq_valid     (wPushOk),
    .io_enq_bits_addr (wqAddr),
    .io_dClk          (io_ddr_clk),
    .io_dRstn         (io_ddr_rstn),
    .io_deq_ready     (_awCdc_io_deq_ready),
    .io_deq_valid     (_awCdc_io_deq_valid),
    .io_deq_bits_addr (io_ddrAwAddr)
  );
  assign _wCdc_io_sRstn = ~reset;
  assign _wCdc_io_enq_bits_data = {wrBuf_3, wrBuf_2, wrBuf_1, wrBuf_0};
  assign _wCdc_io_enq_bits_strb = {wrStrb_3, wrStrb_2, wrStrb_1, wrStrb_0};
  CdcFifo_1 wCdc (
    .io_sClk          (clock),
    .io_sRstn         (_wCdc_io_sRstn),
    .io_enq_ready     (_wCdc_io_enq_ready),
    .io_enq_valid     (wPushOk),
    .io_enq_bits_data (_wCdc_io_enq_bits_data),
    .io_enq_bits_strb (_wCdc_io_enq_bits_strb),
    .io_enq_bits_id   (wqId),
    .io_enq_bits_last (wBeatOut_last),
    .io_dClk          (io_ddr_clk),
    .io_dRstn         (io_ddr_rstn),
    .io_deq_ready     (wTake),
    .io_deq_valid     (_wCdc_io_deq_valid),
    .io_deq_bits_data (io_ddrWData),
    .io_deq_bits_strb (io_ddrWStrb),
    .io_deq_bits_id   (_wCdc_io_deq_bits_id),
    .io_deq_bits_last (_wCdc_io_deq_bits_last)
  );
  assign _arCdc_io_sRstn = ~reset;
  assign _arCdc_io_deq_ready = arGo & io_ddrArReady;
  CdcFifo arCdc (
    .io_sClk          (clock),
    .io_sRstn         (_arCdc_io_sRstn),
    .io_enq_ready     (_arCdc_io_enq_ready),
    .io_enq_valid     (arSplit),
    .io_enq_bits_addr (arAddr),
    .io_dClk          (io_ddr_clk),
    .io_dRstn         (io_ddr_rstn),
    .io_deq_ready     (_arCdc_io_deq_ready),
    .io_deq_valid     (_arCdc_io_deq_valid),
    .io_deq_bits_addr (io_ddrArAddr)
  );
  assign _rCdc_io_dRstn = ~reset;
  assign _rCdc_io_deq_ready = _rCdc_io_deq_ready_T & io_axi_r_rready;
  CdcFifo_3 rCdc (
    .io_sClk      (io_ddr_clk),
    .io_sRstn     (io_ddr_rstn),
    .io_enq_ready (_rCdc_io_enq_ready),
    .io_enq_valid (io_ddrRValid),
    .io_enq_bits  (io_ddrRData),
    .io_sOcc      (_rCdc_io_sOcc),
    .io_dClk      (clock),
    .io_dRstn     (_rCdc_io_dRstn),
    .io_deq_ready (_rCdc_io_deq_ready),
    .io_deq_valid (_rCdc_io_deq_valid),
    .io_deq_bits  (_rCdc_io_deq_bits)
  );
  assign _doneCdc_io_enq_valid = wTake & _wCdc_io_deq_bits_last;
  assign _doneCdc_io_dRstn = ~reset;
  CdcFifo_4 doneCdc (
    .io_sClk      (io_ddr_clk),
    .io_sRstn     (io_ddr_rstn),
    .io_enq_valid (_doneCdc_io_enq_valid),
    .io_enq_bits  (_wCdc_io_deq_bits_id),
    .io_dClk      (clock),
    .io_dRstn     (_doneCdc_io_dRstn),
    .io_deq_ready (io_axi_b_bready),
    .io_deq_valid (_doneCdc_io_deq_valid),
    .io_deq_bits  (io_axi_b_bid)
  );
  assign _awQ_io_enq_bits_addr = io_axi_aw_awaddr[29:2];
  Queue8_AwCmd awQ (
    .clock            (clock),
    .reset            (reset),
    .io_enq_ready     (_awQ_io_enq_ready),
    .io_enq_valid     (_awQ_io_enq_valid_T_1),
    .io_enq_bits_addr (_awQ_io_enq_bits_addr),
    .io_enq_bits_len  (io_axi_aw_awlen),
    .io_enq_bits_id   (io_axi_aw_awid),
    .io_deq_ready     (wLoad),
    .io_deq_valid     (_awQ_io_deq_valid),
    .io_deq_bits_addr (_awQ_io_deq_bits_addr),
    .io_deq_bits_len  (_awQ_io_deq_bits_len),
    .io_deq_bits_id   (_awQ_io_deq_bits_id)
  );
  assign _rdQ_io_deq_ready = rFire & io_axi_r_rlast_0;
  Queue8_RdBurst rdQ (
    .clock           (clock),
    .reset           (reset),
    .io_enq_ready    (_rdQ_io_enq_ready),
    .io_enq_valid    (_rdQ_io_enq_valid_T),
    .io_enq_bits_id  (io_axi_ar_arid),
    .io_enq_bits_len (io_axi_ar_arlen),
    .io_deq_ready    (_rdQ_io_deq_ready),
    .io_deq_valid    (_rdQ_io_deq_valid),
    .io_deq_bits_id  (io_axi_r_rid),
    .io_deq_bits_len (_rdQ_io_deq_bits_len)
  );
  assign io_axi_ar_arready = arReady;
  assign io_axi_r_rdata = _io_axi_r_rdata_T_2[63:0];
  assign io_axi_r_rresp = 2'h0;
  assign io_axi_r_rlast = io_axi_r_rlast_0;
  assign io_axi_r_rvalid = io_axi_r_rvalid_0;
  assign io_axi_aw_awready = _awQ_io_enq_ready & ~(outW[2]);
  assign io_axi_w_wready = io_axi_w_wready_0;
  assign io_axi_b_bresp = 2'h0;
  assign io_axi_b_bvalid = _doneCdc_io_deq_valid;
  assign io_ddrAwLen = 4'h0;
  assign io_ddrAwValid = _awCdc_io_deq_valid;
  assign io_ddrArLen = 4'h0;
  assign io_ddrArValid = arGo;
  assign io_dbgOutW = outW;
  assign io_dbgOutR = outR;
  assign io_dbgMaxOutW = maxOutW;
  assign io_dbgMaxOutR = maxOutR;
endmodule

